const get=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}},set=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
let activeAccountId=(()=>{let session=get("wowfood_demo_session",null);return typeof session?.identifier==="string"?session.identifier:"anonymous"})();
function userGet(key,fallback){return get(`${key}_${encodeURIComponent(activeAccountId)}`,fallback)}
function userSet(key,value){set(`${key}_${encodeURIComponent(activeAccountId)}`,value)}
let language=get("wowfood_language","en")==="km"?"km":"en";
function t(key,values={}){let value=TEXT[language][key]||TEXT.en[key]||key;return value.replace(/\{(\w+)\}/g,(match,name)=>values[name]??match)}
function categoryName(category){let keys={Burger:"burgerCategory",Pizza:"pizzaCategory",Chicken:"chickenCategory",Khmer:"khmerCategory",Desserts:"dessertCategory",Drinks:"drinkCategory"};return t(keys[category]||category)}
function foodName(food){let names={7:"lokLak",8:"fishAmok",9:"baiSachChrouk",10:"kuyTeav",11:"nomBanhChok",13:"khmerCoffee",14:"sugarcane",15:"coconutWater",16:"dessertSpecial",17:"chocolateDessert",18:"sweetDessert",19:"creamyDessert",20:"fruitDessert",21:"bakeryDessert",22:"dessertTreat",23:"dessertDelight",24:"sweetCake",30:"stingDrink",31:"primeDrink"},key=names[food.id]||`food_${food.id}`;return TEXT[language][key]||food.name}
function setLanguage(next){language=next==="km"?"km":"en";set("wowfood_language",language);applyLanguage();let error=$("#loginError"),key=loginErrorKeys[error.textContent];if(key)error.textContent=t(key);if(page==="Favourites")$("#pageTitle").textContent=t("favourites")}
function applyLanguage(){document.documentElement.lang=language;document.documentElement.dataset.language=language;document.querySelectorAll("[data-i18n]").forEach(el=>{let key=el.dataset.i18n;if(el.tagName==="OPTION")el.textContent=t(key);else el.textContent=t(key)});document.querySelectorAll("[data-i18n-placeholder]").forEach(el=>el.placeholder=t(el.dataset.i18nPlaceholder));document.querySelectorAll("[data-i18n-aria]").forEach(el=>el.setAttribute("aria-label",t(el.dataset.i18nAria)));document.querySelectorAll("[data-i18n-title]").forEach(el=>el.title=t(el.dataset.i18nTitle));$("#loginHeroTitle").innerHTML=language==="km"?"អាហារដែលអ្នកចូលចិត្ត<br>បញ្ជាទិញបានត្រឹមតែ<br><em>ចុចមួយប៉ុណ្ណោះ។</em>":TEXT.en.loginHeroTitle.replace("favorite meal","favorite meal<br>").replace("just a click away.","just a <em>click away.</em>");document.querySelectorAll("[data-language-toggle]").forEach(button=>{button.textContent=language==="en"?"ខ្មែរ":"English";button.setAttribute("aria-label",language==="en"?"ប្តូរភាសា":"Switch language")});$("#loginForm").elements.password.autocomplete=authMode==="signup"?"new-password":"current-password";setAuthMode(authMode);renderCategoryFilters();syncSortControls();renderRestaurants();renderFoods();if(page==="Menu")renderMenu();if(page==="Favourites")renderFavorites();if(!["Explore","Menu","Favourites"].includes(page))pageChange(page);renderCart()}
let cart=userGet("wowfood_cart",[]).filter(x=>FOODS.some(f=>f.id===x.id)),favs=userGet("wowfood_favorites",[]).filter(id=>FOODS.some(f=>f.id===id)),orders=userGet("wowfood_orders",[]),deliveryMessages=userGet("wowfood_delivery_messages",{}),profile=userGet("wowfood_profile",{name:"",email:"",phone:""}),page="Explore",selectedRestaurant=null,activeMessageOrderId=null,selectedCategory="All",sortMode="featured",restaurantRadius=10;
if(!deliveryMessages||typeof deliveryMessages!=="object"||Array.isArray(deliveryMessages))deliveryMessages={};
function toast(s){let aliases={"Added to cart!":"addedCart","Favorites updated":"favoritesUpdated","Your cart is empty":"emptyCartToast","Profile saved!":"profileSaved","Order placed! You can contact delivery in Messages.":"orderSuccess","Pickup option selected":"pickupSelected","Menu sorted by lowest price. All items are 20% off.":"dealsToast","Unable to sign out. Check browser storage settings and try again.":"signoutError"},key=aliases[s]||s,element=$("#toast");element.textContent=TEXT[language][key]?t(key):s;element.classList.add("show");setTimeout(()=>element.classList.remove("show"),2200)}
function renderRestaurants(){let q=$("#searchInput").value.toLowerCase();$("#restaurantGrid").innerHTML=RESTAURANTS.filter(r=>(r.name+" "+r.kind+" "+t(`restaurantKind${r.kind}`)).toLowerCase().includes(q)&&Number.parseFloat(r.distance)<=restaurantRadius).map(r=>`<button class="restaurant-card ${selectedRestaurant===r.name?"selected":""}" type="button" data-restaurant="${r.name}" aria-pressed="${selectedRestaurant===r.name}"><span class="restaurant-logo">${r.logo}</span><span><span class="restaurant-name">${r.name}</span><span class="restaurant-meta"><span class="stars">★ ${r.rating}</span><span>${t(`restaurantKind${r.kind}`)||r.kind}</span><span>♧ ${r.distance}</span></span><span class="restaurant-foot"><span>${r.fee.replace(" delivery",` ${t("delivery")}`)}</span><span>›</span></span></span></button>`).join("")||`<p class="empty">${t("noRestaurants")}</p>`}
function foodCards(list){return list.map(f=>{let name=foodName(f);return`<article class="food-card"><div class="food-photo"><img src="${f.image}" alt="${name}" loading="lazy" onerror="this.onerror=null;this.src='assets/food-placeholder.svg'"><span class="discount-badge">${t("twentyOff")}</span><button class="food-fav ${favs.includes(f.id)?"active":""}" data-fav="${f.id}" aria-label="${t("toggleFoodFavourite",{name})}">${favs.includes(f.id)?"♥":"♡"}</button></div><div class="food-info"><h3>${name}</h3><p><span>★ ${f.rating}</span> ${categoryName(f.category)} · ◷ ${f.time}</p><div class="food-bottom"><span class="food-price"><del class="regular-price">${money(regularPrice(f.price))}</del><span>${money(f.price)}</span></span><button class="add-btn" data-add="${f.id}" aria-label="${t("addToCart",{name})}">+</button></div></div></article>`}).join("")}
function sortFoods(items){let sorted=[...items];if(sortMode==="rating")sorted.sort((a,b)=>Number(b.rating)-Number(a.rating));if(sortMode==="price-low")sorted.sort((a,b)=>a.price-b.price);if(sortMode==="price-high")sorted.sort((a,b)=>b.price-a.price);return sorted}
function filteredFoods(items,q){return sortFoods(items.filter(f=>(selectedCategory==="All"||f.category===selectedCategory)&&(f.name+" "+foodName(f)+" "+f.category+" "+categoryName(f.category)+" "+f.restaurant).toLowerCase().includes(q)))}
function categoryFilterMarkup(){return`<button type="button" class="category-chip ${selectedCategory==="All"?"active":""}" data-category="All" aria-pressed="${selectedCategory==="All"}">${t("categoryAll")}</button>${CATEGORIES.map(category=>`<button type="button" class="category-chip ${selectedCategory===category?"active":""}" data-category="${category}" aria-pressed="${selectedCategory===category}">${categoryName(category)}</button>`).join("")}`}
function renderCategoryFilters(){["homeCategoryFilters","menuCategoryFilters","favoriteCategoryFilters"].forEach(id=>{let container=$("#"+id);if(container)container.innerHTML=categoryFilterMarkup()})}
function syncSortControls(){$("#homeSortSelect").value=sortMode;$("#menuSortSelect").value=sortMode}
function renderFoods(){let q=$("#searchInput").value.toLowerCase(),restaurant=RESTAURANTS.find(r=>r.name===selectedRestaurant),matching=restaurant?FOODS.filter(f=>f.restaurant===restaurant.name):[],category=restaurant?(restaurant.kind==="Pizza"?"Pizza":restaurant.kind==="Chicken"?"Chicken":"Burger"):null,source=restaurant?(matching.length?matching:FOODS.filter(f=>f.category===category)):FOODS,list=filteredFoods(source,q);$("#foodHeading").textContent=restaurant?(matching.length?t("restaurantsFrom",{restaurant:restaurant.name}):t("foodOptions",{category:categoryName(category)})):t("popularHeading");$("#clearRestaurant").hidden=!restaurant;$("#foodGrid").innerHTML=foodCards(list)||`<p class="empty">${t("noFoodMatch")}</p>`}
function renderMenu(){let q=$("#searchInput").value.toLowerCase(),categories=selectedCategory==="All"?CATEGORIES:[selectedCategory];$("#menuFoodSections").innerHTML=categories.map(category=>{let items=filteredFoods(FOODS.filter(f=>f.category===category),q);return items.length?`<section class="menu-category"><div class="section-title"><h2>${categoryName(category)}</h2></div><div class="food-grid">${foodCards(items)}</div></section>`:""}).join("")||`<p class="empty">${t("noMenuMatch")}</p>`}
function renderFavorites(){let q=$("#searchInput").value.toLowerCase(),items=filteredFoods(FOODS.filter(f=>favs.includes(f.id)),q);$("#favoriteFoodGrid").innerHTML=foodCards(items)||`<p class="empty">${t("noFavourites")}</p>`}
function total(){let sub=cart.reduce((s,x)=>s+FOODS.find(f=>f.id===x.id).price*x.qty,0),fee=sub===0||sub>25?0:1.5;return{sub,fee,all:sub+fee}}
function renderCart(){let n=cart.reduce((s,x)=>s+x.qty,0),totals=total();$("#cartCount").textContent=n;$("#cartItemsCount").textContent=`(${n})`;$("#subtotal").textContent=money(totals.sub);$("#delivery").textContent=totals.fee?money(totals.fee):t("free");$("#total").textContent=money(totals.all);$("#formTotal").textContent=money(totals.all);$("#cartList").innerHTML=cart.map(x=>{let f=FOODS.find(y=>y.id===x.id),name=foodName(f);return `<div class="cart-row"><img src="${f.image}" alt="${name}" onerror="this.onerror=null;this.src='assets/food-placeholder.svg'"><div><h4>${name}</h4><small class="cart-price"><del class="regular-price">${money(regularPrice(f.price))}</del><span>${money(f.price)}</span> · 20% ${t("off")}</small><div class="qty"><button data-qty="${f.id}" data-d="-1">−</button>${x.qty}<button data-qty="${f.id}" data-d="1">+</button></div></div><button class="remove" data-remove="${f.id}">${t("remove")}</button></div>`}).join("")||`<div class="empty">🛒<h3>${t("emptyCartTitle")}</h3>${t("emptyCartText")}</div>`}
