function renderOrders(){let list=$("#ordersList");if(!orders.length){list.innerHTML=`<p class="empty">${t("noOrders")}</p>`;return}list.innerHTML=orders.map(o=>{let items=Array.isArray(o.items)?o.items:[];let itemList=items.map(item=>{let food=FOODS.find(f=>f.id===item.id);return food?`<li><span>${foodName(food)} × ${item.qty}</span><b>${money(food.price*item.qty)}</b></li>`:""}).filter(Boolean).join("");return `<article class="order-card"><div class="order-heading"><div><b>${t("orderLabel")} #${o.id}</b><small>${o.date}</small></div><b class="order-total">${money(o.total)}</b></div><ul class="order-items">${itemList||`<li>${t("itemUnavailable")}</li>`}</ul><div class="order-footer"><span>${o.count} ${t(o.count===1?"item":"items")}</span><span class="order-status">${t("orderPlaced")}</span></div></article>`}).join("")}
function escapeHtml(value){return String(value).replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[char]))}
function renderSettings(){$("#secondaryContent").innerHTML=`<section class="settings-card"><div class="settings-card-heading"><span class="settings-icon" aria-hidden="true">👤</span><div><h3>${t("manageAccount")}</h3><p>${t("updateProfile")}</p></div></div><dl class="settings-account"><div><dt>${t("profileName")}</dt><dd>${escapeHtml(profile.name||t("notSet"))}</dd></div><div><dt>${t("email")}</dt><dd>${escapeHtml(profile.email||t("notSet"))}</dd></div><div><dt>${t("profilePhone")}</dt><dd>${escapeHtml(profile.phone||t("notSet"))}</dd></div></dl><button class="orange-btn" type="button" data-edit-profile>${t("editProfile")}</button></section><section class="settings-card cache-settings"><div><h3>${t("clearCacheTitle")}</h3><p>${t("clearCacheDescription")}</p></div><button class="cache-clear-btn" type="button" data-clear-app-cache>${t("clearCacheButton")}</button></section>`}
async function clearAppCache(button){button.disabled=true;button.textContent=t("clearCacheWorking");try{if(!("caches"in window))throw new Error("Cache Storage is unavailable");let cacheNames=(await caches.keys()).filter(name=>name.startsWith("wowfood-dashboard-"));await Promise.all(cacheNames.map(name=>caches.delete(name)));if("serviceWorker"in navigator){let appWorkerUrl=new URL("./sw.js",location.href);let registrations=await navigator.serviceWorker.getRegistrations();await Promise.all(registrations.filter(registration=>[registration.active,registration.waiting,registration.installing].some(worker=>worker&&new URL(worker.scriptURL).origin===appWorkerUrl.origin&&new URL(worker.scriptURL).pathname===appWorkerUrl.pathname)).map(registration=>registration.unregister()))}location.reload()}catch(error){console.error("Failed to clear the WOWFOOD app cache.",error);button.disabled=false;button.textContent=t("clearCacheButton");toast("clearCacheFailed")}}
function renderMessages(){if(!orders.length){$("#secondaryContent").innerHTML=`<div class="message-empty"><p class="empty">${t("noOrderMessages")}</p><button class="orange-btn" type="button" data-open-menu>${t("browseMenu")} →</button></div>`;return}if(!orders.some(o=>String(o.id)===String(activeMessageOrderId)))activeMessageOrderId=orders[0].id;let order=orders.find(o=>String(o.id)===String(activeMessageOrderId)),thread=deliveryMessages[order.id],messages=Array.isArray(thread)?thread.filter(m=>m&&m.sender==="customer"&&typeof m.text==="string"&&typeof m.time==="string"):[];$("#secondaryContent").innerHTML=`<section class="message-page"><div class="message-top"><div><strong>${t("deliveryTeam")}</strong><small>${t("orderConversation")}</small></div><label>${t("orderLabel")}<select id="messageOrder">${orders.map(o=>`<option value="${escapeHtml(o.id)}" ${String(o.id)===String(order.id)?"selected":""}>#${escapeHtml(o.id)} · ${escapeHtml(o.date)}</option>`).join("")}</select></label></div><div class="message-notice">${t("demoChatNotice")}</div><div class="message-thread" aria-live="polite">${messages.map(m=>`<div class="message-row"><p class="message-bubble">${escapeHtml(m.text)}</p><time>${escapeHtml(m.time)}</time></div>`).join("")||`<p class="message-placeholder">${t("messagePrompt")}</p>`}</div><form class="message-compose" id="messageForm"><label class="sr-only" for="deliveryMessage">${t("messages")}</label><textarea id="deliveryMessage" name="message" maxlength="500" required placeholder="${t("messagePlaceholder")}"></textarea><button class="orange-btn" type="submit">${t("sendMessage")} →</button></form></section>`;let threadElement=$("#secondaryContent .message-thread");threadElement.scrollTop=threadElement.scrollHeight}
function pageChange(p){page=p;document.querySelectorAll(".nav-link").forEach(a=>a.classList.toggle("active",a.dataset.page===p));$("#explore").hidden=p!=="Explore";$("#menuPage").hidden=p!=="Menu";$("#secondaryPage").style.display=["Explore","Menu"].includes(p)?"none":"block";renderCategoryFilters();syncSortControls();if(p==="Menu"){renderMenu();return}if(p==="Favourites"){$("#pageTitle").textContent=t("favourites");$("#secondaryContent").innerHTML=`<div class="category-filters favorites-categories" id="favoriteCategoryFilters" aria-label="${t("filterCategory")}"></div><div class="food-grid" id="favoriteFoodGrid"></div>`;renderCategoryFilters();renderFavorites();return}if(p==="Explore"){$("#foodHeading").textContent=t("popularHeading");renderFoods()}else{$("#pageTitle").textContent=p==="About"?t("aboutTitle"):t(p.toLowerCase());$("#secondaryContent").innerHTML=p==="Orders"?'<div id="ordersList"></div>':p==="Settings"?"":p==="About"?`<div class="about-page"><p class="about-intro">${t("aboutIntro")}</p><p>${t("aboutText")}</p><div class="about-highlights"><article><span>🍽️</span><h3>${t("somethingForEveryone")}</h3><p>${t("foodVariety")}</p></article><article><span>📍</span><h3>${t("neighborhood")}</h3><p>${t("findNearby")}</p></article><article><span>💛</span><h3>${t("easyStart")}</h3><p>${t("easySteps")}</p></article></div></div>`:"";if(p==="Orders")renderOrders();if(p==="Messages")renderMessages();if(p==="Settings")renderSettings()}}
